import assert from 'node:assert/strict';
const { createGate } = await import(process.argv[2]);
const d = (s) => new Date(s);
const LA = 'America/Los_Angeles', BE = 'Europe/Berlin';
let g = createGate();
const r = (o) => g.request({ userId: 'u', timeZone: LA, category: 'promo', ...o });
// LA midnight = 08:00Z (PDT, Oct)
let a = r({ now: d('2026-10-20T07:00:00Z') }); assert(a.allowed && a.rule === '' && a.id); // Oct 19 LA
let b = r({ now: d('2026-10-20T08:00:00Z') }); assert(b.allowed); // Oct 20 LA, 1h later across midnight
assert.equal(r({ now: d('2026-10-20T08:30:00Z') }).rule, 'min-gap');
assert(r({ now: d('2026-10-20T10:00:00Z') }).allowed); // exactly 2h
assert(r({ now: d('2026-10-20T12:00:00Z') }).allowed);
let c = r({ now: d('2026-10-20T14:00:00Z') }); assert.deepEqual([c.allowed, c.rule, c.id], [false, 'daily-cap', null]);
assert(r({ now: d('2026-10-21T07:59:00Z') }).rule === 'daily-cap'); // still Oct 20 LA
assert(r({ now: d('2026-10-21T08:00:00Z') }).allowed); // new LA day
// security unaffected
assert(g.request({ userId: 'u', timeZone: LA, category: 'security', now: d('2026-10-20T08:01:00Z') }).allowed);
// cancel frees slot
g = createGate();
const x = r({ now: d('2026-10-20T08:00:00Z') });
assert.equal(r({ now: d('2026-10-20T08:30:00Z') }).rule, 'min-gap');
g.cancel(x.id); g.cancel(x.id); g.cancel('nope');
assert(r({ now: d('2026-10-20T08:30:00Z') }).allowed);
// security alone doesn't consume gap
g = createGate();
g.request({ userId: 'u', timeZone: LA, category: 'security', now: d('2026-10-20T08:00:00Z') });
assert(r({ now: d('2026-10-20T08:01:00Z') }).allowed);
// per-user + tz: Berlin day boundary
g = createGate();
const q = (now, userId='b') => g.request({ userId, timeZone: BE, category: 'promo', now: d(now) });
assert(q('2026-10-20T20:00:00Z').allowed && q('2026-10-20T22:30:00Z').allowed && q('2026-10-20T23:00:00Z').rule === 'min-gap');
assert(q('2026-10-21T00:30:00Z').allowed); // 02:30 Berlin next day? 22:30Z=00:30 Oct21 Berlin; fine
assert(q('2026-10-20T20:00:00Z', 'other').allowed);
assert.equal(g.request({ userId: 'b', timeZone: 'Nope/Zone', category: 'promo', now: d('2026-10-25T00:00:00Z') }).rule, 'invalid-time-zone');
console.log('ok');
EOF
node /tmp/gt/test.mjs "$PWD/bot.mjs"
